    const plank = (ox, a, b, ln, seam) => { for (let y = WALL_H, row = 0; y < FY; y += 4, row++) { rect(g, ox, y, RW, 4, row % 2 ? b : a); rect(g, ox, y, RW, 1, ln); for (let x = ox + (row * 11) % 26; x < ox + RW; x += 26) rect(g, x, y, 1, 4, seam); } };
    const carpet = (ox, base, dot) => { rect(g, ox, WALL_H, RW, FY - WALL_H, base); for (let y = WALL_H + 2; y < FY; y += 3) for (let x = ox + 4 + (Math.floor(y / 3) % 2) * 2; x < ox + RW - 4; x += 4) rect(g, x, y, 1, 1, dot); };
    tiles(0, '#3a3f52', '#363b4e', '#313547', 12);
    carpet(RW, '#1b1f31', '#222842');
    plank(2 * RW, '#2e211c', '#33251f', '#271b17', '#22180f');
    carpet(3 * RW, '#133746', '#18455a');
    plank(4 * RW, '#342622', '#3a2b26', '#2c201c', '#271c18');
    tiles(5 * RW, '#262d40', '#293148', '#22283a', 16);
    tiles(6 * RW, '#2b303c', '#2b303c', '#252a35', 8);
    tiles(7 * RW, '#3b3f4f', '#30344a', '#2c3042', 8);
    plank(8 * RW, '#43332c', '#493830', '#3a2c26', '#33261f');
